\label{cor:free}
  The group of free homotopy classes of homotopy self-equivalences of $M$ is
  isomorphic to $\operatorname{Aut}_{\bullet}^{+}(M)\cong(\mathbb{Z}/2)^4$.

\label{def:gauss}
The \emph{stable normal Gauss map} of a smooth manifold $M^n$ is the map
$\nu_M\colon M\toBO$ classifying the stable normal bundle.

\label{prop:kernel}
  $\ker\pi=\{k_\kappa:\kappa\in\pi_4(M)\}$ and $\kappa\mapsto k_\kappa$ is injective.
  Hence $\ker\pi\cong\pi_4(M)\cong(\mathbb{Z}/2)^2$.

\label{lem:transport}
The homomorphism $u_*\colon\Omega^B_n(X)\to\Omega^B_n(Y)$ does not depend on $H$, only on the based
homotopy class of $u$, and $(vu)_*=v_*u_*$, $(\operatorname{id})_*=\operatorname{id}$.

\label{def:alpha}
For $f\in\operatorname{Aut}^+_\bullet(M)$ put $\alpha(f)=f_*[M,\mathrm{id},\sigma]-[M,\mathrm{id},\sigma]\in\widehat\Omega^B_4(M)$.
The structure $\sigma$ lives on the source and does not depend on $f$.

\label{prop:crossed}
For $f,g\in\operatorname{Aut}^+_\bullet(M)$ one has $\alpha(fg)=\alpha(f)+f_*\alpha(g)$. Consequently
$\ker\alpha$ is a subgroup, and $\alpha(f)=\alpha(g)$ if and only if $g^{-1}f\in\ker\alpha$.

\label{prop:AHSS}
In the twisted Atiyah--Hirzebruch spectral sequence $E^2_{p,q}=H_p(M;\Omega^{\mathrm{spin}}_q\otimes\mathbb{Z}^{w})\Rightarrow\Omega^B_{p+q}(M)$,
all differentials leaving or entering total degree $4$ vanish, and $|\widehat\Omega^B_4(M)|=16$.
The $E^\infty$ terms in total degree $4$ are
\[
\begin{array}{c|ccccc}
(p,q)&(4,0)&(3,1)&(2,2)&(1,3)&(0,4)\\\hline
E^\infty&\mathbb{Z}&\mathbb{Z}/2&(\mathbb{Z}/2)^2&0&\mathbb{Z}/2
\end{array}
\]

\label{prop:detect}
Let $j\colon S^2\to M$, $j(y)=(x_0,y)$, let $\kappa_2=j\circ\eta_2\eta_3$ be a generator of the second summand of $\pi_4(M)$ and let
$\kappa_1=q\circ\eta_2\eta_3$ be a generator of the first, where $q\colon S^2\to\mathbb{R}P^2\subset M$ is the double cover. Then in $\widehat\Omega^B_4(M)$:
\begin{enumerate}[label=(\roman*)]
  \item $\alpha(k_{\kappa_2})\ne0$, and $\alpha(k_{\kappa_2})$ is represented by $[S^2]\otimes\eta^2\ne0$ in $E^\infty_{2,2}$;
  \item $\alpha(k_{\kappa_1})=[K3\to\mathrm{pt}]\ne0$, the generator of $E^\infty_{0,4}=\mathbb{Z}/2$.
\end{enumerate}

\label{rem:k1}
\Cref{prop:kernel} (A) and \cref{prop:detect} (ii) are two independent proofs that $k_{\kappa_1}\ne\operatorname{id}$. The element $\alpha(k_{\kappa_1})$ is the class of a K3 surface in $E^\infty_{0,4}=\mathbb{Z}/2$, a term through which $\alpha$ does not pass in the oriented spin case, where the kernel of $\pi$ is detected in $E_{2,2}$ \cite[Proposition~4.5 and Corollary~4.9]{HK04}. For simply connected manifolds the pinch maps are detected by their normal invariants \cite[Theorems~2.2 and~5.1]{CH90}.
Here the normal invariant does not detect $k_{\kappa_1}$ through its $H^2$-component. Indeed, by Hypothesis~\ref{hyp:pinch} (\cref{sec:hyp}) the $H^2$-component of the normal invariant of the pinch map $k_{y\circ\eta^2}$ is $\mathrm{PD}\,h(y)$, where $h\colon\pi_2(M)\to H_2(M;\mathbb{Z}/2)$ is the mod~$2$ Hurewicz map and $\mathrm{PD}$ is the Poincar\'e duality isomorphism $H_2(M;\mathbb{Z}/2)\to H^2(M;\mathbb{Z}/2)$. For the class $y_1\in\pi_2(M)$ coming from the double cover $q$ we have $h(y_1)=q_*[S^2]=2[\mathbb{R}P^2]=0$, whereas $h(y_2)=[S^2]\ne0$ for the $S^2$-factor. So, assuming Hypothesis~\ref{hyp:pinch}, the non-trivial self-equivalence $k_{\kappa_1}$ has vanishing $H^2$-component of its normal invariant.

\label{prop:Q6M}
Let $\mathcal S(M)=\mathcal S^{\mathrm{TOP}}(M)$ be the topological structure set, and $\mathcal H\le\operatorname{Aut}_{\bullet}(M)$ the subgroup of classes
homotopic to a homeomorphism. Assume Hypothesis~\ref{hyp:sigma} for (i)--(iii) and Hypothesis~\ref{hyp:pinch} for (iv). Then
\begin{enumerate}[label=(\roman*)]
 \item $\ast(\mathbb{R}P^2\times S^2)\simeq\mathbb{R}P^2\times S^2$, and $|\mathcal S(M)|=4$ under Hypothesis~\ref{hyp:sigma};
 \item $[\operatorname{Aut}_{\bullet}(M):\mathcal H]=2$, so $|\mathcal H|=16$;
 \item $\mathcal H\cap K$ has order $2$, where $K=\langle k_{\kappa_1},k_{\kappa_2}\rangle=\ker\pi$, and $\mathcal H\supseteq S=\langle a,b,s_\psi\rangle$;
 \item $\mathcal H\cap K=\langle k_{\kappa_1}\rangle$, so $k_{\kappa_2}$ and $k_{\kappa_1}k_{\kappa_2}$ are not homotopic to homeomorphisms, and the $H^2(M;\mathbb{Z}/2)$-component of the normal invariant of $k_{\kappa_2}$ is $a^2$.
\end{enumerate}
